True def transform(grid):
    g=[row[:] for row in grid]
    r=c=0
    for i,row in enumerate(g):
        for j,x in enumerate(row):
            if x==2: r,c=i,j
    # Trace straight from marker to board edge horizontally, and downward until obstacle.
    for j in range(len(g[0])):
        if g[r][j]==0: g[r][j]=2
    for i in range(r+1,len(g)):
        if g[i][c]==8: break
        if g[i][c]==0: g[i][c]=2
    return g
